CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "Role" AS ENUM ('OWNER','ADMIN','MARKETER','VIEWER');
CREATE TYPE "UserStatus" AS ENUM ('PENDING','ACTIVE','DISABLED');
CREATE TYPE "ContactStatus" AS ENUM ('SUBSCRIBED','UNSUBSCRIBED','BOUNCED','COMPLAINED','PENDING_CONFIRMATION');
CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT','SCHEDULED','PREPARING','QUEUED','SENDING','PAUSED','COMPLETED','CANCELLED','FAILED');
CREATE TYPE "RecipientStatus" AS ENUM ('PENDING','QUEUED','SENDING','SENT','DELIVERED','BOUNCED','COMPLAINED','FAILED','SUPPRESSED');
CREATE TYPE "ImportStatus" AS ENUM ('UPLOADED','PROCESSING','COMPLETED','FAILED','CANCELLED');

CREATE TABLE tenants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,plan TEXT NOT NULL DEFAULT 'free',status TEXT NOT NULL DEFAULT 'active',timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,email TEXT NOT NULL,normalized_email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role "Role" NOT NULL DEFAULT 'OWNER',status "UserStatus" NOT NULL DEFAULT 'PENDING',email_verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,id));
CREATE INDEX users_tenant_id_idx ON users(tenant_id);
CREATE TABLE sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,tenant_id UUID NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX sessions_expires_at_idx ON sessions(expires_at); CREATE INDEX sessions_tenant_id_idx ON sessions(tenant_id);
CREATE TABLE one_time_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,purpose TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX one_time_tokens_user_id_purpose_expires_at_idx ON one_time_tokens(user_id,purpose,expires_at);
CREATE TABLE contacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,email TEXT NOT NULL,normalized_email TEXT NOT NULL,first_name TEXT,last_name TEXT,status "ContactStatus" NOT NULL DEFAULT 'PENDING_CONFIRMATION',consent_source TEXT,consent_at TIMESTAMPTZ,custom_fields JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,normalized_email),UNIQUE(tenant_id,id));
CREATE INDEX contacts_tenant_status_idx ON contacts(tenant_id,status); CREATE INDEX contacts_tenant_email_idx ON contacts(tenant_id,email);
CREATE TABLE contact_lists (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE list_contacts (tenant_id UUID NOT NULL,list_id UUID NOT NULL,contact_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,list_id,contact_id),FOREIGN KEY(tenant_id,list_id) REFERENCES contact_lists(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE templates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,subject TEXT,html_content TEXT NOT NULL,text_content TEXT,editor_json JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,id));
CREATE TABLE campaigns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,subject TEXT,preview_text TEXT,from_name TEXT,from_email TEXT,reply_to TEXT,list_id UUID,template_id UUID,html_content TEXT,text_content TEXT,status "CampaignStatus" NOT NULL DEFAULT 'DRAFT',scheduled_at TIMESTAMPTZ,quota_date DATE,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,list_id) REFERENCES contact_lists(tenant_id,id),FOREIGN KEY(tenant_id,template_id) REFERENCES templates(tenant_id,id));
CREATE INDEX campaigns_tenant_status_idx ON campaigns(tenant_id,status);
CREATE TABLE campaign_recipients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,campaign_id UUID NOT NULL,contact_id UUID NOT NULL,email TEXT NOT NULL,status "RecipientStatus" NOT NULL DEFAULT 'PENDING',provider_message_id TEXT,sent_at TIMESTAMPTZ,delivered_at TIMESTAMPTZ,quota_reserved BOOLEAN NOT NULL DEFAULT TRUE,unsubscribe_token_hash TEXT UNIQUE,unsubscribe_token_encrypted TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(campaign_id,contact_id),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,campaign_id) REFERENCES campaigns(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id));
CREATE INDEX campaign_recipients_tenant_status_idx ON campaign_recipients(tenant_id,status);
CREATE TABLE email_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,recipient_id UUID NOT NULL,event_type TEXT NOT NULL,event_key TEXT,url TEXT,event_data JSONB NOT NULL DEFAULT '{}'::jsonb,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,event_key),FOREIGN KEY(tenant_id,recipient_id) REFERENCES campaign_recipients(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX email_events_tenant_recipient_type_idx ON email_events(tenant_id,recipient_id,event_type);
CREATE TABLE webhook_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),provider TEXT NOT NULL,provider_event_id TEXT NOT NULL UNIQUE,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'received',attempts INTEGER NOT NULL DEFAULT 0,processed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX webhook_deliveries_status_created_idx ON webhook_deliveries(status,created_at);
CREATE TABLE suppressions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,email TEXT NOT NULL,normalized_email TEXT NOT NULL,reason TEXT NOT NULL,source TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,normalized_email));
CREATE TABLE unsubscribes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,contact_id UUID,email TEXT NOT NULL,reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX unsubscribes_tenant_email_idx ON unsubscribes(tenant_id,email);
CREATE TABLE tenant_sending_limits (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(id) ON DELETE CASCADE,daily_limit INTEGER NOT NULL DEFAULT 500,monthly_limit INTEGER NOT NULL DEFAULT 15000,contact_limit INTEGER NOT NULL DEFAULT 10000,enabled BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE daily_usage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,usage_date DATE NOT NULL,sent_count INTEGER NOT NULL DEFAULT 0,reserved_count INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,usage_date));
CREATE TABLE platform_daily_usage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),usage_date DATE NOT NULL UNIQUE,sent_count INTEGER NOT NULL DEFAULT 0,reserved_count INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE sending_domains (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,domain TEXT NOT NULL,verification_status TEXT NOT NULL DEFAULT 'pending',dkim_status TEXT NOT NULL DEFAULT 'pending',spf_status TEXT NOT NULL DEFAULT 'unknown',dmarc_status TEXT NOT NULL DEFAULT 'unknown',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,domain));
CREATE TABLE import_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,file_key TEXT NOT NULL,status "ImportStatus" NOT NULL DEFAULT 'UPLOADED',total_rows INTEGER NOT NULL DEFAULT 0,imported_rows INTEGER NOT NULL DEFAULT 0,duplicate_rows INTEGER NOT NULL DEFAULT 0,rejected_rows INTEGER NOT NULL DEFAULT 0,suppressed_rows INTEGER NOT NULL DEFAULT 0,processed_rows INTEGER NOT NULL DEFAULT 0,attempt INTEGER NOT NULL DEFAULT 0,csv_headers JSONB,field_mapping JSONB,destination_list_id UUID,consent_source TEXT,consent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),completed_at TIMESTAMPTZ,UNIQUE(tenant_id,id));
CREATE TABLE import_errors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,import_job_id UUID NOT NULL,row_number INTEGER NOT NULL,email TEXT,reason TEXT NOT NULL,row_data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(import_job_id,row_number),FOREIGN KEY(tenant_id,import_job_id) REFERENCES import_jobs(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX import_errors_tenant_job_row_idx ON import_errors(tenant_id,import_job_id,row_number);
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id UUID,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX audit_logs_tenant_created_idx ON audit_logs(tenant_id,created_at);

-- Use a non-owner API role and install app.tenant_id with SET LOCAL for every authenticated request.
DO $$ DECLARE t TEXT; BEGIN
 FOREACH t IN ARRAY ARRAY['contact_lists','list_contacts','contacts','templates','campaigns','campaign_recipients','email_events','suppressions','unsubscribes','tenant_sending_limits','daily_usage','sending_domains','import_jobs','import_errors','audit_logs'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t);
 END LOOP;
END $$;
ALTER POLICY tenant_isolation ON campaign_recipients
 USING (tenant_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid OR unsubscribe_token_hash = NULLIF(current_setting('app.unsubscribe_token_hash',true),''))
 WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
